void _runMissing(String root) {
  _write('$root/a/js/bad.js', """
function action(params) { require('./nope/missing.js'); return 1; }
""");
  const JsJobRunner().runScript(
    scriptPath: '$root/a/js/bad.js',
    jobParams: const {},
