  final cfgDir = Directory('$root/cfg2')..createSync();
  final cfgFile = File('${cfgDir.path}/agent.json')
    ..writeAsStringSync(jsonEncode({'postJSAction': 'only-in-cwd.js'}));
  return jsonDecode(const RunCommandProcessor().process(
